#!/usr/bin/env python3
"""Render the shell model table from the same pinned profiles as the engine."""

from pathlib import Path
import shlex

try:
    from .model_catalog import MODELS, profile
except ImportError:
    from model_catalog import MODELS, profile


def render():
    lines = [
        "# Generated by tools/generate_launchers.py.",
        "select_model() {",
        '    case "$model" in',
    ]
    for size in MODELS:
        p = profile(size)
        lines += [
            f"        {size})",
            f"            model_name={shlex.quote(p.name)}",
            f"            revision={p.revision}",
            f"            relative_directory={shlex.quote(str(p.directory))}",
            "            weight_files=(" + " ".join(shlex.quote(n) for n in p.weights) + ")",
            "            ;;",
        ]
    lines += [
        "        *)",
        "            printf 'plamo: choose --model 0.8b, 2b, 8b, or 31b\\n' >&2",
        "            return 2",
        "            ;;",
        "    esac",
        "}",
    ]
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    (Path(__file__).resolve().parents[1] / "nix/model-profiles.sh").write_text(render())
